import { HeatmapAdapter } from '@dreadnought/react/unstyled';
const columns = [{ id: 'mon', label: 'Пн' }, { id: 'tue', label: 'Вт' }];
const rows = [{ id: 'team', label: 'Команда' }];
const data = [{ column: 'mon', row: 'team', value: 0 }, { column: 'tue', row: 'team', value: 10 }];
export function Example() { return <HeatmapAdapter label="Закрытые задачи" columns={columns} rows={rows} data={data} domain={[0, 10]} />; }
